// Skip first 10 rows
const rows = items.slice(10);

// Desired headers
const headers = [
  "Date",
  "Particulars",
  "Vch Type",
  "Vch No.",
  "Debit Amount",
  "Credit Amount",
  "undefined",
  "undefined",
  "undefined",
  "undefined"
];

// Excel serial → ISO date
function excelDateToISO(serial) {
  if (typeof serial !== "number") return serial;
  const base = new Date(Date.UTC(1899, 11, 30));
  return new Date(base.getTime() + serial * 86400000)
    .toISOString()
    .slice(0, 10);
}

const output = rows.map(item => {
  const values = Object.values(item.json);
  const newRow = {};

  headers.forEach((h, idx) => {
    let val = values[idx] ?? null;

    // ✅ Correct Date column
    if (h === "Date") {
      val = excelDateToISO(val);
    }

    newRow[h] = val;
  });

  return { json: newRow };
});

return output;

const output = [];

let currentDate = null;
let currentParty = null;
let inInvoice = false;

const isISODate = v =>
  typeof v === "string" && /^\d{4}-\d{2}-\d{2}$/.test(v);

// ✅ Units OPTIONAL now
const qtyRegex  = /^[\d.]+(\s*(nos|ltr|kg|pcs))?$/i;
const rateRegex = /^[\d.]+(\s*\/\s*(nos|ltr|kg|pcs))?$/i;

for (const item of items) {
  const r = item.json;

  /* 1️⃣ Detect invoice header */
  if (isISODate(r.Date)) {
    inInvoice = r["Vch Type"] === "Sales";
    currentDate  = inInvoice ? r.Date : null;
    currentParty = inInvoice ? r.Particulars : null;
    continue;
  }

  /* 2️⃣ Product rows under Tax Invoice */
  if (
    inInvoice &&
    currentDate &&
    currentParty &&
    typeof r.Date === "string" &&
    qtyRegex.test(String(r.Particulars || "")) &&
    rateRegex.test(String(r["Vch Type"] || "")) &&
    typeof r["Vch No."] === "number"
  ) {
    output.push({
      "order date": currentDate,
      "party name": currentParty,
      "product": r.Date,
      "quantity": r.Particulars,
      "price/unit": r["Vch Type"],
      "order value": r["Vch No."]
    });
  }
}

return output.map(o => ({ json: o }));

const rows = items.map(i => i.json);

rows.sort((a, b) => {
  const da = new Date(a["order date"]);
  const db = new Date(b["order date"]);

  if (isNaN(da) && isNaN(db)) return 0;
  if (isNaN(da)) return 1;
  if (isNaN(db)) return -1;

  return da - db;
});

return rows.map(r => ({ json: r }));

